${pagingTop} SELECT book_review_idx, book_review_loan_id, book_review_web_id, book_review_name, book_review_content, book_review_score, manage_code, book_key, add_id, add_date, modify_id, modify_date FROM BOOK_REVIEW WHERE manage_code = #{manage_code}
AND ${search_type} LIKE '%'||#{search_text}||'%'
ORDER BY book_review_idx DESC ${pagingBottom}

${pagingTop}
SELECT
	book_review_idx, book_review_loan_id, book_review_web_id, book_review_content, book_review_score,
	manage_code, book_key, add_id, add_date, modify_id, modify_date
FROM
	BOOK_REVIEW
WHERE
	book_review_loan_id = #{book_review_loan_id}

AND	book_review_content LIKE '%'||#{search_text}||'%'


AND (TO_DATE(add_date) >= TO_DATE(#{search_start_date}) AND TO_DATE(add_date) <= TO_DATE(#{search_end_date}))


AND manage_code = #{search_loca}

ORDER BY book_review_idx DESC
${pagingBottom}

SELECT COUNT(*) FROM BOOK_REVIEW WHERE book_review_loan_id = #{book_review_loan_id}
AND book_review_content LIKE '%'||#{search_text}||'%'
AND (TO_DATE(add_date) >= TO_DATE(#{search_start_date}) AND TO_DATE(add_date) <= TO_DATE(#{search_end_date}))
AND manage_code = #{search_loca}
ORDER BY book_review_idx DESC
